/*
 * BENCH: EditorScene batches, user transforms, scene restore and context reads
 * TIER: HIGH
 * SUBJECT: apps/desktop/src/features/assistant/EditorScene.ts#execute, #applyUserTransform, #restore, #context, #idOf, #objectIds
 * MEASURES: latency
 * COMPLEXITY: execute O(objects + inner parts); restore O(steps x objects); context O(objects); idOf O(objects)
 * INPUTS: objects 100..1600 (the app caps a scene at 2000), imported parts 1k..16k, history 50..400 steps;
 *         generated by fixtures/scene.fixtures.ts with seed 20260402
 * BASELINE: baselines/editor/execute.baseline.json
 * THRESHOLD: fail if median regresses >25% (and beyond 3x the baseline spread) or p95 >40%
 * EXCLUDES: scene construction, WebGL (no renderer is created)
 * CLIFF: with an imported model of 16k parts the per-part cost doubles as the part list leaves the CPU cache.
 *        Before the single-pass adopt in EditorScene it was quadratic: n^2.4, 4.8 ms at 16k parts.
 * NOTES: every transform edit the user makes, by hand or by dragging, goes through execute, so its cost is
 *        felt on each drag end. The assistant's batches use the same path.
 */
import { describe, it } from "vitest";
import { Scene } from "three";
import { EditorScene } from "@/features/assistant/EditorScene";
import { measureCases, type BenchCase } from "../../lib/harness";
import { finishWithGrowth } from "../../lib/report";
import { consume } from "../../lib/sink";
import { buildEditor, flatModel, moveCommand } from "../../fixtures/scene.fixtures";

const OBJECT_COUNTS = [100, 200, 400, 800, 1600];
const PART_COUNTS = [1000, 2000, 4000, 8000, 16000];
const STEP_COUNTS = [50, 100, 200, 400];

describe("editor scene", () => {
  it("applies a user transform in time that grows linearly with the scene", async () => {
    const cases: BenchCase[] = OBJECT_COUNTS.map((objects) => {
      const built = buildEditor(objects);
      let x = 0;
      return {
        name: "applyUserTransform",
        params: { objects },
        run: () => {
          x += 1;
          const edit = built.editor.applyUserTransform("obj_0", {
            position: [x, 0, 0],
            rotation: [0, 0, 0],
            scale: [1, 1, 1],
          });
          consume(edit.applied ? 1 : 0);
        },
      };
    });
    const results = await measureCases(cases);
    finishWithGrowth("editor/execute.objects", results, [{ key: "objects", declared: 1 }]);
  });

  it("applies a transform to a scene holding an imported model with many parts", async () => {
    const cases: BenchCase[] = PART_COUNTS.map((parts) => {
      const scene = new Scene();
      const editor = new EditorScene(scene, "prj_bench");
      editor.importObject("model", flatModel(parts));
      let x = 0;
      return {
        name: "applyUserTransform(imported model)",
        params: { parts },
        run: () => {
          x += 1;
          consume(
            editor.applyUserTransform("model", { position: [x, 0, 0], rotation: [0, 0, 0], scale: [1, 1, 1] }).applied
              ? 1
              : 0,
          );
        },
      };
    });
    const results = await measureCases(cases);
    // Memory-bound: per-part cost rises from ~65 ns to ~150 ns once 16k parts no longer fit in cache, so the
    // measured exponent runs about 0.5 above linear without any super-linear step (see the bench card).
    finishWithGrowth("editor/execute.parts", results, [{ key: "parts", declared: 1, tolerance: 0.6 }]);
  });

  it("restores a scene by replaying its history, in time linear in the history", async () => {
    const cases: BenchCase[] = STEP_COUNTS.map((steps) => {
      const steplist = [
        ...Array.from({ length: 2 }, (_, batch) => ({
          kind: "commands" as const,
          proposalId: `create-${batch}`,
          commands: Array.from({ length: 50 }, (_unused, index) => ({
            commandId: `box-${batch * 50 + index}`,
            type: "geometry.create_primitive",
            objectId: `obj_${batch * 50 + index}`,
            primitive: "box",
            size: 1,
            replaceExisting: false,
          })),
        })),
        ...Array.from({ length: steps }, (_, index) => ({
          kind: "commands" as const,
          proposalId: `edit-${index}`,
          commands: [moveCommand(`obj_${index % 100}`, index)],
        })),
      ];
      return {
        name: "restore",
        params: { steps },
        async: true,
        run: () => {
          const editor = new EditorScene(new Scene(), "prj_bench");
          return editor
            .restore(steplist, () => Promise.reject(new Error("no imports in this fixture")))
            .then(() => consume(editor.currentRevision));
        },
      };
    });
    const results = await measureCases(cases);
    // Restoring is asynchronous: its promise settles within the timed call because nothing awaits real I/O.
    finishWithGrowth("editor/execute.restore", results, [{ key: "steps", declared: 1 }]);
  });

  it("creates a batch of same-named shapes in time linear in the scene", async () => {
    // Every shape is named "box", the worst case for keeping sibling names unique: each one takes the next
    // free number. The batch is removed again so the scene keeps its size from one run to the next.
    const BATCH = 200;
    const cases: BenchCase[] = OBJECT_COUNTS.map((objects) => {
      const built = buildEditor(objects);
      const extra = Array.from({ length: BATCH }, (_, index) => `extra_${index}`);
      const creates = extra.map((objectId) => ({
        commandId: `create-${objectId}`,
        type: "geometry.create_primitive",
        objectId,
        primitive: "box",
        size: 1,
        replaceExisting: false,
      }));
      const removes = extra.map((objectId) => ({ commandId: `remove-${objectId}`, type: "scene.delete_object", objectId }));
      let runs = 0;
      return {
        name: "create 200 same-named shapes",
        params: { objects },
        run: () => {
          runs += 1;
          const created = built.editor.execute(`create-${runs}`, built.editor.currentRevision, creates);
          if (created.status !== "applied") throw new Error("The batch was rejected");
          const removed = built.editor.execute(`remove-${runs}`, built.editor.currentRevision, removes);
          consume(removed.status === "applied" ? 1 : 0);
        },
      };
    });
    const results = await measureCases(cases);
    // The scene is copied for each mixed batch, so the cost is linear in the scene. Before the batch kept an
    // index of the names under each parent it also rescanned the siblings and searched for a free number from
    // 1 for every shape: 399 ms to create 2000 shapes in batches of 200, against 134 ms with no naming at all.
    finishWithGrowth("editor/execute.create", results, [{ key: "objects", declared: 1, tolerance: 0.4 }]);
  });

  it("reads the scene for the assistant and finds objects in time linear in the scene", async () => {
    const reads: BenchCase[] = [];
    for (const objects of OBJECT_COUNTS) {
      const built = buildEditor(objects);
      const target = built.editor.getObject("obj_0");
      if (!target) throw new Error("fixture has no first object");
      reads.push(
        { name: "context", params: { objects }, run: () => consume(built.editor.context().objects.length) },
        { name: "idOf", params: { objects }, run: () => consume(built.editor.idOf(target)?.length ?? 0) },
        { name: "objectIds", params: { objects }, run: () => consume(built.editor.objectIds()) },
      );
    }
    const results = await measureCases(reads);
    finishWithGrowth(
      "editor/execute.reads",
      results,
      // context copies every object, so it is linear (it allocates, hence the wider tolerance). idOf walks
      // up a few parents and objectIds hands out a lookup, so neither depends on the scene size.
      [
        { name: "context", declared: 1, tolerance: 0.4 },
        { name: "idOf", declared: 0, tolerance: 0.4 },
        { name: "objectIds", declared: 0, tolerance: 0.4 },
      ].map(({ name, declared, tolerance }) => ({
        key: "objects",
        declared,
        tolerance,
        label: name,
        where: (result) => result.name === name,
      })),
    );
  });
});
